package com.yigongbao.backup.cleanup;
import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.*;
class CleanupServiceTest { @Test void onlyActiveMatchingPermitCanDelete(){List<String> deleted=new ArrayList<>(); CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return new Evaluation("t",List.of("a"),1);} public Permit pollPermit(String t){return new Permit("p",t,List.of("a","b"),"ACTIVE");} public void delete(Permit p,String k){if(k.equals("b"))throw new RuntimeException("fail");deleted.add(k);}}; var s=new CleanupService(c); assertThat(s.dryRun(180).taskId()).isEqualTo("t"); var r=s.execute("t"); assertThat(r.deleted()).isEqualTo(1); assertThat(r.failedKeys()).containsExactly("b"); assertThat(deleted).containsExactly("a"); }
 @Test void usesLocalCosDeleterInsteadOfRemoteDeleteCommand(){List<String> deleted=new ArrayList<>(); CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return null;} public Permit pollPermit(String t){return new Permit("p",t,List.of("a"),"ACTIVE");} public void delete(Permit p,String k){throw new AssertionError("remote delete must not be called");}}; com.yigongbao.backup.backup.CosObjectClient cos=new com.yigongbao.backup.backup.CosObjectClient(){public java.io.InputStream download(String k){return java.io.InputStream.nullInputStream();} public void delete(String k,CleanupClient.Permit p){deleted.add(k);}}; assertThat(new CleanupService(c,cos).execute("t").deleted()).isEqualTo(1); assertThat(deleted).containsExactly("a"); }
 @Test void rejectsRevokedPermit(){CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return null;} public Permit pollPermit(String t){return new Permit("p",t,List.of("a"),"REVOKED");} public void delete(Permit p,String k){}}; assertThatThrownBy(()->new CleanupService(c).execute("t")).isInstanceOf(IllegalStateException.class); }
}
